for args in "--output-format json --help" "--output-format yaml --help" "--verbose --help" "-v --version" "--output-format json --version" "--output-format json build --json-only" "build --output-format json --json-only" "--bad" "build --bad" "serve --port abc" "serve --port -1" "dev --port abc" "dev -i foo -i bar --no-first-build"; do
 echo "### $args"; timeout 5 "$ROOT/executable" $args >out 2>err; st=$?; echo STATUS:$st; echo OUT:; cat out; echo ERR:; cat err; echo;
done | sed -n '1,260p'"}

{"command":"ROOT=$(pwd); TMPBASE=$(mktemp -d); cat > /tmp/run_pty_oranda3.py <<'PY'
import os,pty,subprocess,time,select,sys
root=os.environ['ROOT']; args=[root+'/executable','generate','ci']+os.environ.get('ARGS','').split()
resps=[p.encode('latin1').decode('unicode_escape').encode('latin1') for p in os.environ.get('RESPS','\\r,\\r,\\r').split(',')]
master,slave=pty.openpty(); p=subprocess.Popen(args,stdin=slave,stdout=slave,stderr=slave,cwd=os.getcwd(),close_fds=True); os.close(slave)
idx=0; start=time.time(); next_send=None; seen_any=False
while time.time()-start<15:
    r,_,_=select.select([master],[],[],0.05)
    if r:
        try: data=os.read(master,4096)
        except OSError: break
        if not data: break
        seen_any=True; os.write(sys.stdout.fileno(),data)
        if idx < len(resps) and next_send is None:
            next_send=time.time()+0.35
    if idx < len(resps) and next_send is not None and time.time()>=next_send:
        os.write(master,resps[idx]); idx+=1; next_send=None
    if p.poll() is not None:
        time.sleep(.2)
        try:
            while True:
                data=os.read(master,4096)
                if not data: break
                os.write(sys.stdout.fileno(),data)
        except OSError: pass
        break
if p.poll() is None:
    p.terminate(); time.sleep(.3)
    if p.poll() is None: p.kill()
print('\nPY_STATUS',p.returncode)
PY
for combo in y_n_n n_n_n y_y_n y_y_y; do d="$TMPBASE/$combo"; mkdir "$d"; cd "$d"; case $combo in y_n_n) resps='y\r,\r,\r';; n_n_n) resps='n\r,\r,\r';; y_y_n) resps='y\r,y\r,\r';; y_y_y) resps='y\r,y\r,y\r';; esac; echo "### $combo"; ROOT="$ROOT" RESPS="$resps" python3 /tmp/run_pty_oranda3.py >run.out 2>&1; sed -n '1,100p' run.out | cat -v; echo FILES; find . -maxdepth 5 -type f -printf '%p %s\n' | sort; find . -path '*.yml' -o -path '*.yaml' | while read f; do echo WF:$f; sed -n '1,260p' "$f"; done; echo GITIGNORE; cat .gitignore 2>/dev/null || true; done; rm -rf "$TMPBASE""}

